    else if (fk.kind === 'json' && m === 'Tree') box.appendChild(jsonPane(parsed, tools));
    else box.appendChild(codePane(text, fk.kind === 'md' ? 'code' : fk.kind, fk.kind === 'md' ? outlineOf(text, 'md', fk.ext) : outlineOf(text, fk.kind, fk.ext), tools));
